"use strict";(self.webpackChunkultimatelearning=self.webpackChunkultimatelearning||[]).push([[69],{4069:e=>{e.exports=JSON.parse('{"topic":{"id":"java-memory-model","title":"Java Memory Model (Simple Version)","overviewSimple":"Imagine your school where each student has a desk (stack), and all students share a playground (heap). Java memory works the same way \u2014 some data is kept in personal space, some in shared space.","overviewTechnical":["Java Memory Model defines how threads interact with memory.","Main memory areas: Stack, Heap, Metaspace, PC Registers.","Stack stores method calls and primitive values.","Heap stores objects and arrays.","Garbage Collector automatically removes unused objects."],"story":"A school organized student workspaces: each student had their desk, and toys were kept in a shared box. Java organizes memory just as neatly.","realWorldAnalogy":"Stack = personal notebook, Heap = shared library.","keyPoints":["Stack = method calls + local variables","Heap = objects stored here","Garbage collector clears unused objects","Multithreading rules defined"],"exampleSimple":"int a = 10; // stack\\nString s = new String(\\"Hi\\"); // heap","exampleTechnical":["public class MemoryExample {\\n    public static void main(String[] args) {\\n        int x = 5; // stack\\n        Person p = new Person(\\"John\\"); // heap\\n        p = null; // eligible for GC\\n    }\\n}","class Person {\\n    String name;\\n    Person(String name) {\\n        this.name = name;\\n    }\\n}"],"extraNotes":["Metaspace stores class metadata.","Each thread has its own stack.","Escape analysis helps reduce heap allocations."],"bestPracticesSimple":["Reuse objects when possible","Avoid unnecessary new objects"],"bestPracticesAdvanced":["Be mindful of memory leaks (unused references)","Use profiling tools to monitor memory usage","Prefer immutable objects to avoid accidental sharing"]}}')}}]);